package com.turboio.androidtests;

import android.app.*;import android.content.*;import android.os.*;import android.util.Base64;
import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;

/** Keystore migration on an isolated preference namespace; never reads or changes real task profiles. */
public final class TaskProfilesProbe extends Instrumentation {
 private ClassLoader loader;private int checks;
 private Class<?> type(String name)throws Exception{return loader.loadClass("com.turboio.addon."+name);}
 private Object call(Object obj,String name,Class<?>[] types,Object...args)throws Exception{Class<?> c=obj instanceof Class?(Class<?>)obj:obj.getClass();Method m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(obj instanceof Class?null:obj,args);}
 private Object field(Object obj,String name)throws Exception{Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
 private void check(boolean good,String code){checks++;if(!good)throw new IllegalStateException(code);}
 private JSONObject config(String session,long now)throws Exception{return new JSONObject().put("format","turboio-task-connection/1").put("base_url","https://example.test/v1/agent").put("owner_id","synthetic-settings-probe").put("producer_id","synthetic-phone").put("server_id","synthetic-server").put("token",String.join("",Collections.nCopies(48,"x"))).put("token_id","12345678-1234-4234-8234-123456789012").put("expires_at",java.time.Instant.ofEpochMilli(now+3600000).toString()).put("computer_id","synthetic-computer").put("agent_id","synthetic-agent").put("project_id","synthetic-project").put("session_id",session);}
 private Object connection(JSONObject config)throws Exception{return call(type("TaskConnection"),"parse",new Class<?>[]{byte[].class,long.class},config.toString().getBytes(StandardCharsets.UTF_8),System.currentTimeMillis());}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle report=new Bundle();Context target=getTargetContext();Map<String,?> realBefore=new HashMap<>(target.getSharedPreferences("io_agent_tasks_v1",Context.MODE_PRIVATE).getAll());String name="io_agent_profiles_probe_"+UUID.randomUUID().toString().replace("-","");SharedPreferences isolated=target.getSharedPreferences(name,Context.MODE_PRIVATE);try{
  loader=target.getClassLoader();Class<?> settingsType=type("TaskSettings"),connectionType=type("TaskConnection");Constructor<?> ctor=settingsType.getDeclaredConstructor(Context.class);ctor.setAccessible(true);
  Context wrapped=new ContextWrapper(target){@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return isolated;}};Object store=ctor.newInstance(wrapped);long now=System.currentTimeMillis();JSONObject a=config("codex",now),b=config("hermes",now),c=config("qa",now);
  // Obtain the existing product key, then write an exact v1 ciphertext to isolated preferences.
  call(store,"save",new Class<?>[]{connectionType,boolean.class},connection(a),false);KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);javax.crypto.SecretKey key=(javax.crypto.SecretKey)keys.getKey("io.agent.tasks.config.v1",null);
  Cipher seal=Cipher.getInstance("AES/GCM/NoPadding");seal.init(Cipher.ENCRYPT_MODE,key);seal.updateAAD("io-agent/task-connection/1".getBytes(StandardCharsets.UTF_8));byte[] encrypted=seal.doFinal(new JSONObject().put("connection",a).put("enabled",true).toString().getBytes(StandardCharsets.UTF_8));byte[] sealed=new byte[12+encrypted.length];System.arraycopy(seal.getIV(),0,sealed,0,12);System.arraycopy(encrypted,0,sealed,12,encrypted.length);String old=Base64.encodeToString(sealed,Base64.NO_WRAP);check(isolated.edit().clear().putString("sealed",old).commit(),"LEGACY_SEED_FAILED");
  Object all=call(store,"loadAll",new Class<?>[0]);check(((List<?>)field(all,"profiles")).size()==1&&!isolated.contains("profiles_sealed_v2")&&old.equals(isolated.getString("sealed",null)),"READ_MIGRATED_LEGACY");
  call(store,"save",new Class<?>[]{connectionType,boolean.class},connection(b),true);call(store,"save",new Class<?>[]{connectionType,boolean.class},connection(c),false);all=call(store,"loadAll",new Class<?>[0]);check(((List<?>)field(all,"profiles")).size()==3,"REGISTER_LOST_TARGET");check(old.equals(isolated.getString("single_backup_v1",null)),"LEGACY_BACKUP_CHANGED");
  String binding=(String)call(connection(a),"binding",new Class<?>[0]);call(store,"select",new Class<?>[]{String.class},binding);check((Boolean)field(call(store,"load",new Class<?>[0]),"enabled"),"SELECT_DISABLED_TARGET");call(store,"pause",new Class<?>[]{String.class},binding);
  Object reopened=ctor.newInstance(wrapped),again=call(reopened,"loadAll",new Class<?>[0]);List<?> profiles=(List<?>)field(again,"profiles");check(profiles.size()==3,"REOPEN_LOST_TARGET");int on=0;for(Object p:profiles)if((Boolean)field(p,"enabled"))on++;check(on==1,"PAUSE_AFFECTED_OTHER_TARGET");
  // Validate rollback-readable projection; it must be paused and authenticated with old AAD.
  byte[] projection=Base64.decode(isolated.getString("sealed",""),Base64.NO_WRAP);Cipher read=Cipher.getInstance("AES/GCM/NoPadding");read.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Arrays.copyOf(projection,12)));read.updateAAD("io-agent/task-connection/1".getBytes(StandardCharsets.UTF_8));JSONObject legacy=new JSONObject(new String(read.doFinal(Arrays.copyOfRange(projection,12,projection.length)),StandardCharsets.UTF_8));check(!legacy.getBoolean("enabled")&&legacy.getJSONObject("connection").getString("session_id").equals("codex"),"ROLLBACK_PROJECTION_INVALID");
  String before=isolated.getString("profiles_sealed_v2",null);byte[] tampered=Base64.decode(before,Base64.NO_WRAP);tampered[tampered.length-1]^=1;isolated.edit().putString("profiles_sealed_v2",Base64.encodeToString(tampered,Base64.NO_WRAP)).commit();boolean rejected=false;try{call(reopened,"loadAll",new Class<?>[0]);}catch(InvocationTargetException expected){rejected=true;}check(rejected,"TAMPER_SILENT_FALLBACK");check(isolated.getString("sealed",null)!=null,"TAMPER_REMOVED_LEGACY");
  check(realBefore.equals(target.getSharedPreferences("io_agent_tasks_v1",Context.MODE_PRIVATE).getAll()),"REAL_PREFERENCES_CHANGED");check(target.deleteSharedPreferences(name),"TEST_NAMESPACE_NOT_REMOVED");report.putInt("checks_passed",checks);report.putBoolean("real_android_keystore",true);report.putBoolean("legacy_read_only_until_save",true);report.putBoolean("independent_pause_and_restart",true);report.putBoolean("rollback_projection_paused",true);report.putBoolean("tamper_rejected_without_fallback",true);report.putBoolean("real_task_preferences_touched",false);report.putBoolean("test_namespace_removed",true);report.putBoolean("network_audio_or_ota_started",false);finish(Activity.RESULT_OK,report);
 }catch(Throwable failure){while(failure.getCause()!=null)failure=failure.getCause();report.putString("failure_class",failure.getClass().getSimpleName());String code=failure.getMessage();report.putString("failure_code",code!=null&&code.matches("[A-Z][A-Z0-9_]{0,100}")?code:"SETTINGS_PROBE_FAILED");report.putInt("checks_passed",checks);finish(Activity.RESULT_CANCELED,report);
 }finally{target.deleteSharedPreferences(name);}}
}
